const matVariants=[{id:'ice',name:'冰丝席',hint:'柔软薄席 · 细密编织 · 织带包边'},{id:'rattan',name:'藤席',hint:'平整藤纹 · 紧密编织 · 克制弯曲'},{id:'bamboo',name:'竹席',hint:'硬挺竹片 · 穿线接缝 · 薄平席面'}];
const matVariantPanel=document.createElement('section');matVariantPanel.id='matVariantPanel';matVariantPanel.className='set-variant-flyout mat-variant-flyout';matVariantPanel.hidden=true;matVariantPanel.setAttribute('aria-labelledby','matVariantTitle');
matVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="matVariantTitle">凉席</h2><p>选择实际凉席类别，匹配席面结构与包边</p></div><button type="button" class="set-variant-close" aria-label="收起凉席分类">×</button></div><div class="set-variant-options"><h3>凉席类别</h3><div class="set-variant-grid" role="group" aria-label="凉席类别"></div></div><div class="set-variant-footer"><span>1 张凉席 + 2 只席枕套 · 保持薄平结构</span></div>';
document.body.append(matVariantPanel);
function renderMatVariantControl(){const trigger=document.querySelector('[data-product="mat"]');if(trigger){trigger.classList.add('has-mat-variants');trigger.setAttribute('aria-expanded',String(!matVariantPanel.hidden));trigger.setAttribute('aria-controls','matVariantPanel');const selected=state.product==='mat'&&state.fabricMode==='selected'?matVariants.find(v=>v.id===state.fabric):null;trigger.title=(selected?selected.name:'凉席')+' · 点击展开凉席分类';renderChosenProductLabel(trigger,'凉席',(matVariants.find(v=>v.id===(state.product==='mat'?state.fabric:state.matVariant))||matVariants[0]).name);}}
function closeMatVariants(returnFocus=false){matVariantPanel.hidden=true;renderMatVariantControl();if(returnFocus)document.querySelector('[data-product="mat"]')?.focus()}
function placeMatVariants(){placeProductSubmenu(matVariantPanel,document.querySelector('[data-product="mat"]'),540);}
function selectMatVariant(id){if(state.busy||state.product!=='mat'||!matVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).mat=true;state.fabric=id;state.matVariant=id;state.fabricMode='selected';renderOptions();$('fabric').dispatchEvent(new Event('change',{bubbles:true}));closeMatVariants(true);toast('已选择'+matVariants.find(v=>v.id===id).name)}
function openMatVariants(){if(state.busy||state.product!=='mat')return;const grid=matVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of matVariants){const button=document.createElement('button');button.type='button';button.className='set-variant-option illustrated-variant-option';button.dataset.matVariant=item.id;button.setAttribute('aria-pressed',String(state.fabricMode==='selected'&&state.fabric===item.id));const picture=document.createElement('span');picture.className='product-variant-preview';picture.style.backgroundImage="url('/assets/mat-"+item.id+"-angles-v1.png')";picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+' AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;button.append(picture,name,hint);button.title=item.hint;button.addEventListener('click',()=>selectMatVariant(item.id));grid.append(button)}matVariantPanel.hidden=false;placeMatVariants();renderMatVariantControl();}
matVariantPanel.querySelector('.set-variant-close').onclick=()=>closeMatVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='mat'){if(matVariantPanel.hidden)openMatVariants();else closeMatVariants()}else closeMatVariants();renderMatVariantControl();return;}if(!matVariantPanel.contains(e.target))closeMatVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!matVariantPanel.hidden)closeMatVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="mat"]')&&!state.busy){e.preventDefault();openMatVariants();(matVariantPanel.querySelector('[aria-pressed=true]')||matVariantPanel.querySelector('.set-variant-option'))?.focus();}});
window.addEventListener('resize',()=>closeMatVariants());window.addEventListener('scroll',e=>{if(!matVariantPanel.contains(e.target))closeMatVariants()},{passive:true,capture:true});
new MutationObserver(renderMatVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeMatVariants();renderMatVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderMatVariantControl();
